import heapq

def stable_toposort(graph):
    order = list(graph)
    position = {node: i for i, node in enumerate(order)}
    indegree = {node: 0 for node in order}
    dependents = {node: [] for node in order}

    for node in order:
        for dep in graph[node]:
            if dep not in graph:
                raise ValueError(f"missing dependency: {dep!r} (needed by {node!r})")
            indegree[node] += 1
            dependents[dep].append(node)

    ready = [(position[node], node) for node in order if indegree[node] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        _, node = heapq.heappop(ready)
        result.append(node)

        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, (position[dependent], dependent))

    if len(result) != len(order):
        raise ValueError("cycle detected")

    return result
