def schema_drift(expected, actual):
    def leaf_paths(node, prefix):
        if isinstance(node, dict):
            if node:
                for key in sorted(node):
                    path = f"{prefix}.{key}" if prefix else key
                    yield from leaf_paths(node[key], path)
            else:
                yield prefix
        else:
            yield prefix

    def walk(exp, act, prefix=""):
        for key in sorted(set(exp) | set(act)):
            path = f"{prefix}.{key}" if prefix else key

            if key not in exp:
                yield from leaf_paths(act[key], path)
            elif key not in act:
                yield from leaf_paths(exp[key], path)
            else:
                e = exp[key]
                a = act[key]

                if isinstance(e, dict) and isinstance(a, dict):
                    yield from walk(e, a, path)
                elif isinstance(e, dict) or isinstance(a, dict) or e != a:
                    yield path

    return sorted(set(walk(expected, actual)))

