def merge_payload_ranges(items):
    items = list(items)
    for start, end, _ in items:
        if start > end:
            raise ValueError("start must not be greater than end")

    ordered = sorted(items, key=lambda x: (x[0], x[1]))
    if not ordered:
        return []

    result = []
    cur_start, cur_end, cur_payload = ordered[0]

    for start, end, payload in ordered[1:]:
        if payload == cur_payload and start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            result.append([cur_start, cur_end, cur_payload])
            cur_start, cur_end, cur_payload = start, end, payload

    result.append([cur_start, cur_end, cur_payload])
    return result

def committable_windows(events, watermark):
    result = {}
    for event in events:
        if event["event_time"] <= watermark:
            continue
        result.setdefault(event["window"], []).append(event["value"])
    return result
